'use client';
import { useState, useEffect } from 'react';
import { Building2, MapPin, Star, Plus, CheckCircle, Tag } from 'lucide-react';

export default function HospitalManagement() {
  const [hospitals, setHospitals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  
  // Form State
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    rating: '4.5',
    discount_percentage: '',
    discount_description: '',
    image_url: 'linear-gradient(45deg, #1e293b, #0f172a)' // Default placeholder
  });

  useEffect(() => {
    fetchHospitals();
  }, []);

  const fetchHospitals = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/hospitals');
      if (res.ok) {
        const data = await res.json();
        setHospitals(data);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
        const res = await fetch('http://localhost:5000/api/hospitals', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
        });

        if (res.ok) {
            alert('Hospital Added Successfully!');
            setShowForm(false);
            setFormData({ name: '', location: '', rating: '4.5', discount_percentage: '', discount_description: '', image_url: 'linear-gradient(45deg, #1e293b, #0f172a)' });
            fetchHospitals(); // Refresh list
        } else {
            alert('Failed to add hospital');
        }
    } catch (err) {
        console.error(err);
    }
  };

  if (showForm) {
      return (
          <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
                  <h1>Add New Hospital</h1>
                  <button className="btn btn-outline" onClick={() => setShowForm(false)}>Cancel</button>
              </div>
              
              <div className="glass" style={{ padding: '2rem', maxWidth: '600px' }}>
                  <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                      
                      <div>
                          <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Hospital Name</label>
                          <input 
                            type="text" required 
                            value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})}
                            style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                          />
                      </div>

                      <div>
                          <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Location</label>
                          <div style={{ position: 'relative' }}>
                             <MapPin size={18} style={{ position: 'absolute', left: '12px', top: '14px', color: 'var(--text-muted)' }} />
                             <input 
                                type="text" required 
                                value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem 0.8rem 0.8rem 2.5rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                             />
                          </div>
                      </div>

                      <div style={{ display: 'flex', gap: '1rem' }}>
                          <div style={{ flex: 1 }}>
                              <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Rating</label>
                              <input 
                                type="number" step="0.1" max="5" 
                                value={formData.rating} onChange={e => setFormData({...formData, rating: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                              />
                          </div>
                          <div style={{ flex: 1 }}>
                              <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Discount %</label>
                              <input 
                                type="number" 
                                value={formData.discount_percentage} onChange={e => setFormData({...formData, discount_percentage: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                              />
                          </div>
                      </div>

                      <div>
                          <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Offer Description</label>
                          <input 
                            type="text" placeholder="e.g. Flat 20% OFF on First Consult"
                            value={formData.discount_description} onChange={e => setFormData({...formData, discount_description: e.target.value})}
                            style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                          />
                      </div>

                      <button className="btn btn-primary" style={{ marginTop: '1rem' }}>Add Hospital</button>

                  </form>
              </div>
          </div>
      );
  }

  return (
    <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
            <h1>Hospital Management</h1>
            <button className="btn btn-primary" onClick={() => setShowForm(true)}>
                <Plus size={18} style={{ marginRight: '8px' }} /> Add Hospital
            </button>
        </div>

        <div className="grid-cards">
            {hospitals.map((hospital) => (
                <div key={hospital.id} className="glass" style={{ padding: '0', overflow: 'hidden' }}>
                    <div style={{ height: '150px', background: hospital.image_url || 'linear-gradient(45deg, #1e293b, #0f172a)', position: 'relative' }}>
                        <div style={{ position: 'absolute', top: '10px', left: '10px', background: 'rgba(0,0,0,0.6)', color: '#fff', padding: '4px 8px', borderRadius: '6px', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: '4px' }}>
                            <Star size={12} fill="#fbbf24" stroke="none" /> {hospital.rating}
                        </div>
                    </div>
                    <div style={{ padding: '1.5rem' }}>
                        <h3 style={{ fontSize: '1.2rem', marginBottom: '0.5rem' }}>{hospital.name}</h3>
                        <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
                           <MapPin size={14} /> {hospital.location}
                        </p>
                        
                        {hospital.discount_percentage > 0 && (
                            <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: 'rgba(0, 210, 211, 0.1)', color: 'var(--primary)', padding: '4px 10px', borderRadius: '20px', fontSize: '0.85rem' }}>
                                <Tag size={14} /> {hospital.discount_percentage}% OFF
                            </div>
                        )}
                        
                        <div style={{ marginTop: '1.5rem', display: 'flex', gap: '1rem' }}>
                            <button className="btn btn-outline" style={{ flex: 1, fontSize: '0.9rem' }}>Edit</button>
                            <button className="btn btn-outline" style={{ flex: 1, fontSize: '0.9rem', borderColor: '#ef4444', color: '#ef4444' }}>Remove</button>
                        </div>
                    </div>
                </div>
            ))}
        </div>

        {hospitals.length === 0 && !loading && (
             <div style={{ padding: '4rem', textAlign: 'center', color: 'var(--text-muted)' }}>
                 <Building2 size={48} style={{ marginBottom: '1rem', opacity: 0.5 }} />
                 <h3>No hospitals added yet.</h3>
                 <p>Click "Add Hospital" to onboard your first partner.</p>
             </div>
        )}
    </div>
  );
}
